CREATE TEMPORARY TABLE lab_stock (item_id INT PRIMARY KEY, quantity INT NOT NULL);
INSERT INTO lab_stock VALUES (1, 5), (2, 0);
UPDATE lab_stock SET quantity = quantity + 2 WHERE item_id = 1;
DELETE FROM lab_stock WHERE quantity = 0;
SELECT * FROM lab_stock ORDER BY item_id;
DROP TEMPORARY TABLE lab_stock;
